import math

def count_divisors(n):
    """Counts the number of divisors (tau function)."""
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

max_tau = 0
best_x = 0

for x in range(1, 201):
    n = x * x
    tau_n = count_divisors(n)
    if tau_n > max_tau:
        max_tau = tau_n
        best_x = x

print(f"Maximum tau(x^2) for x <= 200 is: {max_tau}")
print(f"This maximum occurs at x = {best_x}")

def prime_factorization(n):
    """Returns a dictionary of prime factors and their exponents."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_tau_x_squared(x):
    """Calculates tau(x^2) using the prime factorization of x."""
    if x == 1:
        return 1

    factors = prime_factorization(x)

    # If x = p1^a1 * p2^a2 * ..., then x^2 = p1^(2a1) * p2^(2a2) * ...
    # tau(x^2) = (2a1 + 1) * (2a2 + 1) * ...
    tau_x_squared = 1
    for prime, exponent in factors.items():
        tau_x_squared *= (2 * exponent + 1)
    return tau_x_squared

def calculate_C(x):
    """Calculates C(x) = tau(x^2) - 1."""
    return calculate_tau_x_squared(x) - 1

